#!/usr/bin/env bash
# Generated by Phase: IMPLEMENT | Feature: EVOL-062
# ============================================================================
# session-handoff.sh — Stop hook: a fresh session per sub-increment. The hand-off is RECORDED at every stop on a
# sub-increment branch, and the stop is NEVER held — an RDR awaiting the user is a legitimate stop, and a held session
# is what grows the main context (ADR-EVOL-062). Exit 0 always; nothing on stderr; one line on stdout for the user.
# Record: .claude/state/handoff.json {branch, train, head, clean, pushed, closed, at} — the next session's banner names
# it (scripts/validate-governance.sh --banner) and the build resumes from the plan's first unticked task.
# clean = no uncommitted change to a TRACKED file (untracked scratch and the state dir never block a close);
# pushed = HEAD is its upstream; closed = clean and pushed.
# The class comes from the ONE reader (python3 scripts/gate.py branch-class --json); no branch regex lives here.
# ============================================================================
cd "${CLAUDE_PROJECT_DIR:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}" || exit 0
cat >/dev/null   # the payload (session_id, stop_hook_active) decides nothing: this hook never blocks
command -v python3 >/dev/null 2>&1 || exit 0
[ -f scripts/gate.py ] || exit 0
INFO=$(python3 scripts/gate.py branch-class --json 2>/dev/null) || exit 0
CLASS=$(printf '%s' "$INFO" | python3 -c 'import json,sys
try: print(json.load(sys.stdin).get("class") or "")
except Exception: print("")' 2>/dev/null)
[ "$CLASS" = "sub-increment" ] || exit 0
BRANCH=$(git rev-parse --abbrev-ref HEAD 2>/dev/null) || exit 0
HEAD_SHA=$(git rev-parse HEAD 2>/dev/null) || exit 0
CLEAN=false; [ -z "$(git status --porcelain --untracked-files=no 2>/dev/null)" ] && CLEAN=true
PUSHED=false; UP=$(git rev-parse '@{u}' 2>/dev/null) && [ "$UP" = "$HEAD_SHA" ] && PUSHED=true
CLOSED=false; [ "$CLEAN" = true ] && [ "$PUSHED" = true ] && CLOSED=true
mkdir -p .claude/state 2>/dev/null || exit 0
HANDOFF_INFO="$INFO" python3 - "$BRANCH" "$HEAD_SHA" "$CLEAN" "$PUSHED" "$CLOSED" <<'PY' 2>/dev/null || exit 0
import json, os, sys, datetime
info = json.loads(os.environ.get("HANDOFF_INFO") or "{}"); b, h, clean, pushed, closed = sys.argv[1:6]   # the reader's line by env: stdin is this script
rec = {"branch": b, "train": info.get("train"), "head": h, "clean": clean == "true", "pushed": pushed == "true", "closed": closed == "true",
       "at": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")}
open(".claude/state/handoff.json", "w", encoding="utf-8").write(json.dumps(rec) + "\n")
PY
if [ "$CLOSED" = true ]; then
  echo "hand-off: sub-increment $BRANCH closed at ${HEAD_SHA:0:8} (pushed, clean) — start the next sub-increment in a fresh session; it resumes from the plan's first unticked task"
else
  echo "hand-off: sub-increment $BRANCH open at ${HEAD_SHA:0:8} (clean: $CLEAN, pushed: $PUSHED) — the next session resumes here"
fi
exit 0
